--订单号
local orderNo = ARGV[1]
--当前用户id
local userId = tonumber(ARGV[2])
--订单状态改变后的状态码 （已取消）
local orderStatus = tonumber(ARGV[3])
--支付记录状态改变后的状态码 （已取消）
local paymentStatus = tonumber(ARGV[4])
--支付时间
local time = ARGV[5]
--所依赖的redis的key
local ticketOrderKey = KEYS[1]
local ticketPaymentKey = KEYS[2]
local ticketLockKey = KEYS[3]
local warmupTicketPermitKey = KEYS[4]

--获取所取消订单order的信息，并反序列化
ticketOrderKey = ticketOrderKey .. orderNo
local orderJson = redis.call("GET", ticketOrderKey)
local order = cjson.decode(orderJson)
--判断操作订单是否属于当前用户，返回0则不属于
if userId ~= order.userId then
    return 0
end

--将修改后的订单覆盖掉
order.status = orderStatus
orderJson = cjson.encode(order)
redis.call("SET",ticketOrderKey,orderJson)

--获取支付信息，并修改状态并覆盖原支付信息
ticketPaymentKey = ticketPaymentKey .. tostring(order.orderId)
local paymentJson = redis.call("GET", ticketPaymentKey)
local payment = cjson.decode(paymentJson)

payment.status = paymentStatus
--判断当前操作是否是支付成功操作
if paymentStatus == 1 then
   -- 写入支付成功时间戳
   payment.paySuccessTime = time
end

paymentJson = cjson.encode(payment)
redis.call("SET",ticketPaymentKey,paymentJson)

--redis释放预扣库存
ticketLockKey = ticketLockKey .. tostring(order.eventSessionId) ..  tostring(order.ticketLevel)
redis.call("INCRBY",ticketLockKey,-order.ticketTotal)

--取消的订单的票数回到库存
warmupTicketPermitKey = warmupTicketPermitKey .. tostring(order.eventSessionId)
redis.call("HINCRBY",warmupTicketPermitKey,"ticketPermit" .. order.ticketLevel,order.ticketTotal)

--操作成功返回1
return 1



